.ds-warm-noir {--bg: #292624;
--bg-card: #34302d;
--bg-card-hover: #3d3834;
--surface: #34302d;
--border: #58524c;
--text: #eae5df;
--text-muted: #b8b0a7;
--accent: #376dd9;
--accent2: #9db8ee;
--link: #9db8ee;
--accent-btn: #376dd9;
--font-display: 'Sora', 'Segoe UI', sans-serif;
--font-body: 'Manrope', 'Segoe UI', sans-serif;
--radius: 12px;color:var(--text);font-family:var(--font-body);line-height:1.6;} .ds-technical{background:var(--bg-card);padding:1.25rem;border:1px solid var(--border);border-radius:12px;}.ds-summary{display:flex;align-items:center;gap:.65rem;min-height:44px;width:fit-content;padding:.5rem .75rem;border:1px solid var(--border);border-radius:6px;color:var(--text);font-size:.8rem;cursor:pointer;list-style:none;}.ds-summary::-webkit-details-marker{display:none;}.ds-summary:hover{background:var(--bg-card-hover);border-color:var(--text-muted);}.ds-summary:focus-visible{outline:2px solid var(--link);outline-offset:4px;}.ds-show-overview,.ds-technical[open] .ds-show-details{display:none;}.ds-technical[open] .ds-show-overview{display:inline;}.ds-chevron{color:var(--link);display:flex;}.ds-technical[open] .ds-chevron{transform:rotate(180deg);}.ds-description{color:var(--text-muted);font-size:.85rem;line-height:1.8;margin:.75rem 0 0;max-width:80ch;}

.ds-warm-noir {--bg: #292624;
--bg-card: #34302d;
--bg-card-hover: #3d3834;
--surface: #34302d;
--border: #58524c;
--text: #eae5df;
--text-muted: #b8b0a7;
--accent: #376dd9;
--accent2: #9db8ee;
--link: #9db8ee;
--accent-btn: #376dd9;
--font-display: 'Sora', 'Segoe UI', sans-serif;
--font-body: 'Manrope', 'Segoe UI', sans-serif;
--radius: 12px;color:var(--text);font-family:var(--font-body);line-height:1.6;} .ds-nav{display:flex;gap:1.5rem;padding:1rem 1.5rem;background:var(--bg);border-bottom:1px solid var(--border);}.ds-nav-link{display:flex;align-items:center;position:relative;color:var(--text-muted);font-size:1.05rem;text-decoration:none;transition:color .2s;}.ds-nav-link:hover{color:var(--text);text-decoration:none;}.ds-nav-link.ds-active{color:var(--link);}.ds-active::after{content:"";position:absolute;bottom:-.35rem;left:0;right:0;height:2px;border-radius:2px;background:var(--link);}.ds-nav-link:focus-visible{outline:2px solid var(--link);outline-offset:5px;}@media(max-width:900px){.ds-nav{flex-direction:column;gap:1rem;}.ds-nav-link{padding:.5rem 0;}.ds-active::after{display:none;}}@media(prefers-reduced-motion:reduce){.ds-nav-link{transition:none;}}

.ds-warm-noir {--bg: #292624;
--bg-card: #34302d;
--bg-card-hover: #3d3834;
--surface: #34302d;
--border: #58524c;
--text: #eae5df;
--text-muted: #b8b0a7;
--accent: #376dd9;
--accent2: #9db8ee;
--link: #9db8ee;
--accent-btn: #376dd9;
--font-display: 'Sora', 'Segoe UI', sans-serif;
--font-body: 'Manrope', 'Segoe UI', sans-serif;
--radius: 12px;color:var(--text);font-family:var(--font-body);line-height:1.6;} .ds-card{display:flex;flex-direction:column;min-width:0;overflow:hidden;border:1px solid var(--border);border-radius:12px;background:var(--bg-card);color:var(--text);text-decoration:none;transition:border-color .18s ease-out;}.ds-card:hover{border-color:var(--link);text-decoration:none;}.ds-card:focus-visible{outline:2px solid var(--link);outline-offset:5px;}.ds-preview{aspect-ratio:16/9;overflow:hidden;background:var(--bg);border-bottom:1px solid var(--border);}.ds-card-copy{display:flex;flex-direction:column;flex:1;gap:1rem;padding:1.5rem;}.ds-card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem;color:var(--text-muted);font-size:.7rem;}.ds-card-demo{color:var(--text);font-weight:600;}.ds-ticket{font-variant-numeric:tabular-nums;color:var(--link);}.ds-card-title{font-family:var(--font-display);font-size:1.35rem;font-weight:600;letter-spacing:-.02em;line-height:1.4;text-wrap:balance;margin:0;}.ds-card-intro{color:var(--text-muted);font-size:.9rem;line-height:1.8;margin:0;flex:1;}.ds-card-link{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding-top:1rem;margin-top:.15rem;border-top:1px solid var(--border);color:var(--link);font-size:.85rem;font-weight:500;}@media(max-width:600px){.ds-card-copy{padding:1.25rem;}.ds-card-title{font-size:1.25rem;}}@media(prefers-reduced-motion:reduce){.ds-card{transition:none;}} .ds-wfo-diagram{display:flex;align-items:center;justify-content:center;gap:1rem;min-height:12rem;padding:1rem;background:#0a0a1a;color:#e0e0f0;border-bottom:1px solid #45405f}.ds-wfo-node{display:grid;place-items:center;width:5rem;height:5rem;flex:none;border:1px solid #6c5ce7;border-radius:50%;background:#12122a;font-size:.8rem;font-weight:600}.ds-wfo-node-disabled{border-color:#efbd87}.ds-wfo-node span{font-size:.65rem;color:#efbd87}.ds-wfo-link{height:2px;flex:1;background:#a1a1c4}.ds-wfo-link-live{background:#c4a5ff}@media(max-width:480px){.ds-wfo-diagram{gap:.5rem}.ds-wfo-node{width:3rem;height:3rem;font-size:.65rem}.ds-wfo-node span{font-size:.55rem}}
